import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"客户端缓存与一致性","description":"","frontmatter":{"title":"客户端缓存与一致性","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/data/cache-strategy.md","filePath":"frontend/decisions/data/cache-strategy.md","lastUpdated":1785589115000}'),o={name:"frontend/decisions/data/cache-strategy.md"};function i(h,t,l,n,c,s){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="客户端缓存与一致性" tabindex="-1">客户端缓存与一致性 <a class="header-anchor" href="#客户端缓存与一致性" aria-label="Permalink to &quot;客户端缓存与一致性&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>客户端缓存不是一个统一开关。HTTP 缓存、内存查询缓存、Service Worker、浏览器持久存储和页面派生数据具有不同所有者与失效机制。策略应从每类数据允许陈旧多久、谁能修改、离线是否可用和错误代价开始。</p><p>基础机制参见<a href="/frontend/guide/core/web/network/caching">HTTP 缓存</a>、<a href="/frontend/guide/core/application/server-state-cache">服务端状态与缓存</a>和<a href="/frontend/practices/solutions/cache-offline-sync">前端缓存、离线与数据同步</a>。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>缓存可以降低延迟和请求量，也会增加陈旧、重复事实来源和调试难度。对新闻列表，短暂陈旧可能无害；对支付余额，展示旧值可能导致错误操作。不能给整个应用设置一个统一 TTL 后宣称完成一致性设计。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-数据级硬约束" tabindex="-1">2.1 数据级硬约束 <a class="header-anchor" href="#_2-1-数据级硬约束" aria-label="Permalink to &quot;2.1 数据级硬约束&quot;">​</a></h3><ul><li>权限和敏感数据不能进入共享缓存，退出登录后可清除；</li><li>写入成功的定义由服务端决定，客户端缓存不能伪造最终提交；</li><li>金额、库存和权限等关键操作在执行前重新校验；</li><li>缓存键必须包含租户、用户、语言和其他影响响应的维度；</li><li>离线写入必须有幂等标识、冲突策略和用户可见状态。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较读取频率、更新频率、可接受陈旧、响应大小、网络成本、离线价值、写入冲突、失效信号、存储配额、隐私和实现复杂度。</p><h2 id="_3-候选层级" tabindex="-1">3. 候选层级 <a class="header-anchor" href="#_3-候选层级" aria-label="Permalink to &quot;3. 候选层级&quot;">​</a></h2><h3 id="_3-1-不缓存或只在当前渲染复用" tabindex="-1">3.1 不缓存或只在当前渲染复用 <a class="header-anchor" href="#_3-1-不缓存或只在当前渲染复用" aria-label="Permalink to &quot;3.1 不缓存或只在当前渲染复用&quot;">​</a></h3><p>适合高度敏感、变化频繁且读取不重复的数据。最容易保持最新，但会增加网络和等待；即使“不缓存”，浏览器和中间 CDN 的默认行为也要显式确认。</p><h3 id="_3-2-http-与-cdn-缓存" tabindex="-1">3.2 HTTP 与 CDN 缓存 <a class="header-anchor" href="#_3-2-http-与-cdn-缓存" aria-label="Permalink to &quot;3.2 HTTP 与 CDN 缓存&quot;">​</a></h3><p>由 <code>Cache-Control</code>、验证器和缓存键管理静态资源或可共享响应。它最接近数据源、可被多个页面复用，但个性化响应必须使用正确的私有和变化声明。</p><h3 id="_3-3-内存查询缓存" tabindex="-1">3.3 内存查询缓存 <a class="header-anchor" href="#_3-3-内存查询缓存" aria-label="Permalink to &quot;3.3 内存查询缓存&quot;">​</a></h3><p>在当前应用会话中按查询键缓存服务端数据，支持请求去重、过期、后台刷新和写后失效。适合页面间重复读取；刷新页面后通常丢失，不能当离线数据库。</p><h3 id="_3-4-持久缓存与离线存储" tabindex="-1">3.4 持久缓存与离线存储 <a class="header-anchor" href="#_3-4-持久缓存与离线存储" aria-label="Permalink to &quot;3.4 持久缓存与离线存储&quot;">​</a></h3><p>Service Worker、Cache Storage 或 IndexedDB 可跨刷新保留资源和数据，适合离线阅读和弱网工作流。需要版本、迁移、配额、加密边界、冲突和注销清理，复杂度最高。</p><h2 id="_4-一致性策略对比" tabindex="-1">4. 一致性策略对比 <a class="header-anchor" href="#_4-一致性策略对比" aria-label="Permalink to &quot;4. 一致性策略对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>适合</th><th>主要风险</th></tr></thead><tbody><tr><td>固定 TTL</td><td>更新频率可预测、短暂陈旧可接受</td><td>突发更新无法及时反映</td></tr><tr><td>Stale-While-Revalidate</td><td>阅读型内容、需要快速展示</td><td>用户先看到旧值，UI 需表达刷新</td></tr><tr><td>写后按键失效</td><td>本客户端执行的修改</td><td>其他客户端修改仍需事件或短 TTL</td></tr><tr><td>推送失效通知</td><td>多客户端、高更新频率</td><td>断线会漏通知，仍需版本和快照</td></tr><tr><td>乐观更新</td><td>可撤销、冲突低的交互</td><td>失败回滚和并发合并复杂</td></tr><tr><td>每次强校验</td><td>支付、权限、最终提交</td><td>延迟和服务端负载更高</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例是多租户运营台，包含产品目录、订单列表、账户余额、国家字典和离线巡检草稿。</p><table tabindex="0"><thead><tr><th>数据</th><th>缓存决定</th><th>一致性决定</th></tr></thead><tbody><tr><td>版本化静态资源</td><td>CDN 长缓存、文件名哈希</td><td>新版本用新 URL</td></tr><tr><td>国家字典</td><td>HTTP 私有缓存 24 小时</td><td>版本变化后重新验证</td></tr><tr><td>产品目录</td><td>查询缓存 5 分钟，后台刷新</td><td>写后失效；实时事件只作失效提示</td></tr><tr><td>订单列表</td><td>查询缓存 30 秒</td><td>订单更新按键失效，操作前服务端校验</td></tr><tr><td>账户余额</td><td>不持久化，短内存缓存</td><td>支付前强制重新读取并由服务端确认</td></tr><tr><td>巡检草稿</td><td>IndexedDB 持久化</td><td>每条操作有幂等 ID，冲突要求用户处理</td></tr></tbody></table><p>缓存键统一包含租户 ID。切换租户或退出登录时清除对应内存与持久数据，Service Worker 不缓存私有 HTML。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>分层策略能减少重复请求并支持离线草稿，但团队要维护缓存清单、键规范、失效事件和调试工具。用户可能短暂看到旧目录或订单，界面需标识更新时间并在关键动作前验证。</p><p>缓存不应保存唯一业务副本。离线草稿必须能够导出或重新同步，持久结构需要版本迁移。退出某个查询库时，HTTP 契约和数据所有权保持不变，可以逐页面迁移。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>不要对所有接口统一设置同一个 TTL。</li><li>不要缓存 401/403 后继续展示原用户数据。</li><li>不要只按 URL 缓存多租户、语言或权限不同的响应。</li><li>推送失效不保证永不丢失，重连后仍需版本或快照校正。</li><li><code>localStorage</code> 不适合大型、结构化、需要事务的离线数据，也不能安全保存敏感凭证。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>运营台各类数据如何缓存并维持可接受一致性</td></tr><tr><td>硬约束</td><td>租户隔离；余额和权限最终强校验；注销清理；离线草稿不丢</td></tr><tr><td>候选</td><td>不缓存、HTTP、查询缓存、持久离线缓存、分层组合</td></tr><tr><td>决定</td><td>按数据风险组合，见数据矩阵</td></tr><tr><td>接受代价</td><td>缓存清单、失效事件、持久结构迁移和调试成本</td></tr><tr><td>退出路径</td><td>服务端仍为权威；离线操作使用开放 JSON 结构和幂等 API</td></tr><tr><td>监控</td><td>命中率、陈旧修正率、失效延迟、配额失败、同步冲突、租户泄漏为零</td></tr><tr><td>负责人</td><td>各领域数据所有者，平台维护缓存基础设施</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>数据更新频率变化一个数量级、陈旧数据引发高严重度事件、缓存命中低于 20%、持久存储配额失败超过 0.5%、离线需求取消，或租户与隐私模型变化时复查。复查应针对单类数据，不必整体推翻缓存层。</p>',35)])])}const u=a(o,[["render",i]]);export{b as __pageData,u as default};
